(window.DOM_TESTS=window.DOM_TESTS||{})["circulation-1"]={"lecture":"circulation-1","chapters":["cv-introduction","cardiac-muscle","cardiac-conduction","cardiac-cycle","heart-sounds","cardiac-output","co-measurement","hemodynamics","blood-pressure","pulses","venous-return","microcirculation","edema","lymphatics"],"questions":[{"id":"lt-circulation-1:1dc69d8e","chapter":"cv-introduction","section":"2-the-two-major-circulatory-pathways","type":"mechanism","stem":"Blood ejected from the right ventricle returns to the left atrium through which sequence?","options":{"A":"Aorta → systemic capillaries → venae cavae.","B":"Pulmonary artery → lung capillaries → pulmonary veins.","C":"Pulmonary veins → systemic tissue capillaries → venae cavae.","D":"Aorta → coronary sinus → pulmonary veins."},"answer":"B","why":"The right ventricle pumps blood through pulmonary arteries to lung capillaries; pulmonary veins return it to the left atrium.","not":{"A":"That is mainly the systemic circulation after left ventricular ejection.","C":"Pulmonary veins carry blood into the left atrium rather than away from the right ventricle.","D":"The aorta receives systemic output from the left ventricle."}},{"id":"lt-circulation-1:2c94a15f","chapter":"cv-introduction","section":"4-why-is-the-left-ventricular-wall-thicker-than-the-right","type":"mechanism","stem":"Why is the left ventricular wall normally thicker than the right ventricular wall?","options":{"A":"It ejects equal volume against much higher pressure.","B":"It must eject twice the right ventricle's volume.","C":"It relaxes only when the right ventricle contracts.","D":"It works against lower pulmonary vascular resistance."},"answer":"A","why":"The left ventricle drives the high-resistance systemic circuit, requiring greater pressure and wall force than the right ventricle.","not":{"B":"Both ventricles eject approximately equal volumes over time.","C":"Both chambers contract during ventricular systole.","D":"The right ventricle pumps against lower pulmonary resistance."}},{"id":"lt-circulation-1:9d5e67d2","chapter":"cv-introduction","section":"5-systole-and-diastole","type":"mechanism","stem":"When both atrioventricular valves are open and semilunar valves are shut, which process predominates?","options":{"A":"Rapid ventricular ejection into the aorta.","B":"Isovolumetric ventricular contraction.","C":"Ventricular filling during diastole.","D":"Closure of the outflow valves at end systole."},"answer":"C","why":"With ventricular pressure below atrial pressure, AV valves open and blood enters relaxed ventricles while semilunar valves remain closed.","not":{"A":"Ejection requires open semilunar valves.","B":"Isovolumetric contraction occurs after AV valves close.","D":"Outflow valve closure happens near the start of ventricular relaxation."}},{"id":"lt-circulation-1:79f3e1d9","chapter":"cv-introduction","section":"6-cardiac-muscle-and-the-conducting-system","type":"conceptual","stem":"Why can coordinated cardiac pumping continue without a new external nerve impulse for every beat?","options":{"A":"Cardiac cells cannot spontaneously depolarise.","B":"The sinoatrial node supplies the pressure needed for ejection.","C":"The atrial myocardium conducts only during expiration.","D":"Intrinsic pacemaker cells generate rhythmic impulses."},"answer":"D","why":"Specialised cardiac pacemaker cells depolarise spontaneously; autonomic nerves modulate rather than initiate each heartbeat.","not":{"A":"Some conducting cells possess spontaneous automaticity.","B":"The SA node produces electrical impulses, not direct ejection pressure.","C":"Atrial conduction is not limited to expiration."}},{"id":"lt-circulation-1:80db2f43","chapter":"cardiac-muscle","section":"2-intercalated-discs-how-separate-cells-function-together","type":"mechanism","stem":"How can an impulse spread rapidly between adjacent cardiac muscle cells?","options":{"A":"Gap junctions provide low-resistance electrical connections.","B":"Each cell must first receive a motor-neuron endplate signal.","C":"The connective tissue between cells conducts sodium current.","D":"Mechanical desmosomes independently generate pacemaker signals."},"answer":"A","why":"Gap junctions in intercalated discs permit ion current to spread from cell to cell, supporting a functional syncytium.","not":{"B":"Cardiac muscle does not require motor endplates for every contraction.","C":"Connective tissue does not replace electrically coupled membranes.","D":"Desmosomes provide mechanical attachment rather than electrical conductance."}},{"id":"lt-circulation-1:bbd225b4","chapter":"cardiac-muscle","section":"3-the-cardiac-muscle-action-potential","type":"mechanism","stem":"A ventricular action potential has a prolonged plateau. Which membrane currents chiefly sustain it?","options":{"A":"Rapid sodium entry alone throughout the entire plateau.","B":"Increased potassium efflux without any inward current.","C":"Calcium inflow balanced by outward potassium current.","D":"Absence of calcium entry with continued chloride influx."},"answer":"C","why":"Slow inward calcium current and outward potassium current maintain the prolonged plateau before repolarisation.","not":{"A":"Fast sodium influx creates phase 0, not the sustained plateau.","B":"Unopposed potassium efflux would favour repolarisation.","D":"Calcium entry contributes substantially to phase 2."}},{"id":"lt-circulation-1:38af4bc5","chapter":"cardiac-muscle","section":"4-excitation-contraction-coupling-from-electrical-signal-to-force","type":"mechanism","stem":"How does calcium entering through L-type channels activate a much larger ventricular calcium signal?","options":{"A":"It directly hydrolyses ATP within actin.","B":"It triggers calcium release from the sarcoplasmic reticulum.","C":"It causes SERCA to release its stored calcium outward.","D":"It closes ryanodine receptors in the sarcoplasmic reticulum."},"answer":"B","why":"Trigger calcium opens ryanodine receptors, releasing stored calcium in calcium-induced calcium release. This amplifies the small trigger signal into a large intracellular calcium release.","not":{"A":"Calcium binds troponin C; ATP hydrolysis occurs in cross-bridge cycling.","C":"SERCA pumps calcium back into the SR during relaxation.","D":"Ryanodine receptors open rather than close in this mechanism."}},{"id":"lt-circulation-1:68ff337b","chapter":"cardiac-muscle","section":"5-how-does-cardiac-muscle-relax","type":"mechanism","stem":"A drug markedly inhibits SERCA in cardiac muscle. What change in relaxation is expected?","options":{"A":"Faster removal of calcium from cytosol.","B":"Complete elimination of L-type calcium channels.","C":"Shorter calcium transient and stronger relaxation.","D":"Slower calcium removal impairs relaxation."},"answer":"D","why":"SERCA normally resequesters calcium into the SR; inhibiting it prolongs the cytosolic calcium transient and slows relaxation.","not":{"A":"Calcium removal becomes slower, not faster.","B":"SERCA inhibition does not directly abolish membrane L-type channels.","C":"Less reuptake prolongs rather than shortens the cytosolic transient."}},{"id":"lt-circulation-1:af372faf","chapter":"cardiac-muscle","section":"6-why-can-t-cardiac-muscle-undergo-normal-tetanus","type":"mechanism","stem":"What prevents ventricular myocytes from sustaining a normal tetanus?","options":{"A":"Refractoriness lasts through most of contraction.","B":"It contains no contractile actin or myosin filaments.","C":"It lacks voltage-gated calcium channels.","D":"Its action potentials can occur only once in a lifetime."},"answer":"A","why":"The long action potential and absolute refractory period prevent rapid re-excitation and mechanical summation into tetanus.","not":{"B":"Cardiac muscle contains actin and myosin.","C":"Calcium channels are essential for the cardiac plateau.","D":"Cardiac cells repeatedly generate action potentials."}},{"id":"lt-circulation-1:df5fe154","chapter":"cardiac-muscle","section":"7-how-do-the-sympathetic-and-vagal-nerves-change-cardiac-muscle","type":"mechanism","stem":"Beta-1 adrenergic stimulation generally increases ventricular contractility through which sequence?","options":{"A":"Reduced cAMP → less calcium entry → weaker contraction.","B":"Increased vagal tone → reduced pacemaker slope → stronger contraction.","C":"Increased cAMP/PKA signalling → greater calcium availability.","D":"Blocked ryanodine receptors → larger systolic calcium release."},"answer":"C","why":"Beta-1 signalling raises cAMP and PKA activity, enhancing calcium entry and cycling for stronger contraction.","not":{"A":"Beta-1 stimulation raises, not lowers, cAMP.","B":"Vagal slowing is not the main ventricular inotropic pathway.","D":"Blocking release channels would reduce systolic calcium release."}},{"id":"lt-circulation-1:ea704fc0","chapter":"cardiac-conduction","section":"2-the-pathway-of-cardiac-electrical-conduction","type":"mechanism","stem":"Which sequence correctly traces normal electrical conduction from atria into ventricular myocardium?","options":{"A":"SA node → Purkinje fibres → AV node → His bundle.","B":"SA node → AV node → His bundle → Purkinje fibres.","C":"AV node → SA node → left ventricle → right atrium.","D":"Purkinje fibres → atria → SA node → AV node."},"answer":"B","why":"The SA node initiates impulses that reach the AV node, traverse the His–bundle branches and Purkinje system, then depolarise ventricles.","not":{"A":"Purkinje fibres come after the AV–His pathway.","C":"The SA node normally initiates atrial excitation.","D":"Ventricular Purkinje fibres conduct after, not before, atrial activation."}},{"id":"lt-circulation-1:0fc75cc9","chapter":"cardiac-conduction","section":"3-why-is-the-sa-node-the-normal-pacemaker","type":"mechanism","stem":"Why does the sinoatrial node ordinarily set the heart's rhythm rather than latent pacemakers?","options":{"A":"Its cells have the largest ventricular muscle mass.","B":"It receives oxygen from the pulmonary veins first.","C":"Its action potentials last longer than all other cells.","D":"It has the fastest intrinsic depolarisation rate."},"answer":"D","why":"The SA node normally reaches threshold fastest and overdrive-suppresses slower latent pacemakers. Faster SA-node impulses normally suppress slower escape pacemakers.","not":{"A":"Pacemaker dominance does not depend on muscle mass.","B":"Coronary perfusion is not determined by pulmonary venous timing.","C":"Action potential duration is not the primary reason for the fastest spontaneous rate."}},{"id":"lt-circulation-1:948b7db5","chapter":"cardiac-conduction","section":"4-if-other-conducting-cells-can-fire-spontaneously-why-doesn-t-each-set-its-own-rhythm","type":"application","stem":"If the sinoatrial node fails, why may the heart still beat at a slower rate?","options":{"A":"Other conducting tissues retain latent automaticity.","B":"The ventricles require no electrical signal to contract.","C":"The aortic valve becomes an independent pacemaker.","D":"Cardiac nerves directly contract every ventricular cell."},"answer":"A","why":"Subsidiary pacemakers in the AV junction or Purkinje system can spontaneously depolarise, usually at slower rates.","not":{"B":"Coordinated contraction still requires electrical activation.","C":"Valves are passive mechanical structures.","D":"Autonomic nerves modify pacemaking but do not directly activate every myocyte."}},{"id":"lt-circulation-1:a6c2fd9a","chapter":"cardiac-conduction","section":"5-why-does-the-av-node-delay-electrical-conduction","type":"mechanism","stem":"What physiological purpose is served by slow conduction through the AV node?","options":{"A":"It ensures ventricles eject before the atria contract.","B":"It allows the aortic valve to remain open during atrial systole.","C":"It allows atrial contraction to finish ventricular filling.","D":"It prevents the impulse from ever reaching the ventricular myocardium."},"answer":"C","why":"The AV delay separates atrial and ventricular activation so atrial systole can augment ventricular filling before ventricular systole.","not":{"A":"The sequence is atrial activation before ventricular activation.","B":"The aortic valve remains closed during ordinary atrial systole.","D":"Normal impulses subsequently travel through His and Purkinje fibres."}},{"id":"lt-circulation-1:b376a329","chapter":"cardiac-conduction","section":"6-why-is-ventricular-conduction-so-rapid","type":"mechanism","stem":"Why do Purkinje fibres help the two ventricles contract as coordinated pumps?","options":{"A":"They slow excitation until the pulmonary valve closes.","B":"They rapidly activate ventricular myocardium.","C":"They delay the impulse longer than the AV node does.","D":"They selectively depolarise only the atrial septum."},"answer":"B","why":"Rapid His–Purkinje conduction activates much of ventricular myocardium in a short time for synchronised pumping.","not":{"A":"Pulmonary valve closure occurs after ventricular ejection.","C":"The key AV delay occurs before the His–Purkinje network.","D":"Purkinje fibres primarily serve ventricles, not the atrial septum."}},{"id":"lt-circulation-1:012db581","chapter":"cardiac-conduction","section":"8-clinical-significance-of-conduction-disturbances","type":"application","stem":"A ventricular impulse occurs independently of atrial excitation after complete AV conduction block. What has happened?","options":{"A":"The SA node has increased its firing rate.","B":"The aortic valves transmit an alternate impulse.","C":"Atrial excitation now travels directly through the lungs.","D":"A subsidiary escape pacemaker has taken over."},"answer":"D","why":"Complete AV block prevents atrial impulses from reaching ventricles; a slower escape pacemaker may maintain ventricular rhythm.","not":{"A":"Faster atrial activity alone cannot restore complete AV conduction.","B":"Valves do not propagate cardiac electrical impulses.","C":"The lungs do not provide an alternative physiological conduction path."}},{"id":"lt-circulation-1:740028d3","chapter":"cardiac-cycle","section":"3-filling-how-blood-enters-the-relaxed-ventricle","type":"mechanism","stem":"Atrial contraction contributes the final part of ventricular filling. What portion of normal filling does the lecture assign to passive inflow?","options":{"A":"About 70%.","B":"About 30%.","C":"About 10%.","D":"About 100%."},"answer":"A","why":"The lecture describes approximately 70% passive ventricular filling and 30% added by atrial systole.","not":{"B":"The lecture attributes this approximate share to atrial contraction.","C":"Ten per cent is smaller than the lecture's passive portion.","D":"Atrial contraction ordinarily supplies additional filling."}},{"id":"lt-circulation-1:93995ab4","chapter":"cardiac-cycle","section":"4-isovolumetric-contraction-contracting-but-no-blood-leaves","type":"mechanism","stem":"What directly causes atrioventricular valves to close at the beginning of ventricular systole?","options":{"A":"Atrial pressure exceeds ventricular pressure.","B":"Ventricular pressure rises above atrial pressure.","C":"Aortic pressure falls below ventricular pressure.","D":"Coronary pressure falls below right atrial pressure."},"answer":"B","why":"As ventricles start contracting, ventricular pressure exceeds atrial pressure and forces mitral and tricuspid valves shut.","not":{"A":"Higher atrial pressure would favour opening AV valves.","C":"Higher ventricular than aortic pressure opens the aortic valve later.","D":"Coronary pressure does not determine AV-valve closure."}},{"id":"lt-circulation-1:24f48dbb","chapter":"cardiac-cycle","section":"4-isovolumetric-contraction-contracting-but-no-blood-leaves","type":"mechanism","stem":"Which combination correctly characterises isovolumetric ventricular contraction?","options":{"A":"AV valves open, semilunar valves open, volume rises.","B":"AV valves open, semilunar valves shut, volume falls.","C":"All valves closed, ventricular pressure rises, volume fixed.","D":"All valves closed, ventricular pressure falls, volume fixed."},"answer":"C","why":"Both ventricles generate rising pressure with all inlet and outlet valves closed, so neither receives nor ejects blood.","not":{"A":"Open valves permit volume exchange.","B":"AV valves do not remain open once ventricular pressure rises above atrial.","D":"Falling pressure describes isovolumetric relaxation, not contraction."}},{"id":"lt-circulation-1:be5f8461","chapter":"cardiac-cycle","section":"5-ejection-why-blood-finally-leaves","type":"mechanism","stem":"What event ends isovolumetric contraction and begins ventricular ejection?","options":{"A":"Ventricular pressure falls below atrial pressure.","B":"Atrial contraction briefly increases end-diastolic volume.","C":"Ventricular pressure falls below aortic pressure.","D":"Ventricular pressure exceeds the outflow artery pressure."},"answer":"D","why":"Semilunar valves open when ventricular pressure exceeds aortic or pulmonary arterial pressure. The pressure reversal is the immediate mechanical trigger for valve opening.","not":{"A":"This pressure relation opens the AV valves during filling.","B":"Atrial systole precedes isovolumetric contraction.","C":"Lower ventricular than aortic pressure holds the aortic valve closed."}},{"id":"lt-circulation-1:a8ac0cba","chapter":"cardiac-cycle","section":"5-ejection-why-blood-finally-leaves","type":"comparison","stem":"How does ventricular blood outflow change from early to late systole?","options":{"A":"It starts rapidly and then becomes reduced ejection.","B":"It starts slowly and accelerates until valve closure.","C":"It remains identical in flow throughout systole.","D":"It begins only after ventricular relaxation."},"answer":"A","why":"The ejection phase has an initial rapid phase followed by reduced ejection as the pressure and flow relationship changes.","not":{"B":"The pattern is the reverse of the usual ejection phases.","C":"Ejection rate declines rather than remaining uniform.","D":"Ejection occurs during ventricular systole, before relaxation."}},{"id":"lt-circulation-1:c083e7fa","chapter":"cardiac-cycle","section":"7-how-much-blood-does-the-ventricle-pump","type":"calculation","stem":"A ventricle has an end-diastolic volume of 130 mL and an end-systolic volume of 55 mL. What is its stroke volume?","options":{"A":"55 mL.","B":"75 mL.","C":"130 mL.","D":"185 mL."},"answer":"B","why":"Stroke volume is EDV minus ESV, so 130 − 55 = 75 mL per beat.","not":{"A":"Fifty-five mL is end-systolic volume.","C":"One hundred thirty mL is end-diastolic volume.","D":"Adding EDV and ESV does not give stroke volume."}},{"id":"lt-circulation-1:87987e35","chapter":"cardiac-cycle","section":"6-closing-the-outflow-valves-and-isovolumetric-relaxation","type":"mechanism","stem":"What closes the aortic valve at the beginning of ventricular relaxation?","options":{"A":"Atrial pressure rises above left ventricular pressure.","B":"Left ventricular pressure rises above aortic pressure.","C":"Aortic pressure exceeds ventricular pressure.","D":"Venous pressure exceeds aortic pressure."},"answer":"C","why":"When ventricular pressure falls below aortic pressure, brief reversal tendency closes the aortic valve and starts isovolumetric relaxation.","not":{"A":"Atrial pressure governs mitral opening, not aortic closure.","B":"Ventricular pressure exceeding aortic pressure opens the valve.","D":"Venous pressure does not directly determine aortic valve closure."}},{"id":"lt-circulation-1:81b90f2c","chapter":"cardiac-cycle","section":"9-reading-the-wiggers-diagram-one-trace-at-a-time","type":"interpretation","stem":"A Wiggers diagram shows the QRS complex before a steep ventricular pressure rise. What does the QRS represent?","options":{"A":"Beginning of passive atrial filling.","B":"Closure of the pulmonary venous openings.","C":"Completion of ventricular repolarisation.","D":"Electrical activation of the ventricles."},"answer":"D","why":"QRS reflects ventricular electrical activation; mechanical pressure rises after excitation, during isovolumetric contraction. Thus QRS precedes the pressure rise; it does not measure ejection.","not":{"A":"Atrial filling is not the electrical event marked by QRS.","B":"Pulmonary veins do not close as cardiac valves.","C":"Ventricular repolarisation is represented mainly by the T wave."}},{"id":"lt-circulation-1:adab37b1","chapter":"cardiac-cycle","section":"10-right-versus-left-heart-s2-splitting-and-heart-rate","type":"mechanism","stem":"Why can inspiration delay pulmonary valve closure relative to aortic valve closure?","options":{"A":"Inspiration raises right filling and prolongs ejection.","B":"Inspiration stops pulmonary blood flow during systole.","C":"Inspiration causes the aortic valve to close last by default.","D":"Inspiration lowers right ventricular preload to zero."},"answer":"A","why":"Inspiration increases venous return to the right heart and tends to prolong right ventricular ejection, producing physiological S2 splitting.","not":{"B":"Pulmonary flow continues during normal inspiration.","C":"A2 ordinarily precedes P2 during physiological splitting.","D":"Right ventricular filling generally rises rather than disappearing."}},{"id":"lt-circulation-1:670dbf78","chapter":"heart-sounds","section":"2-why-does-s1-occur-before-s2","type":"mechanism","stem":"Which valve event is responsible for the first heart sound?","options":{"A":"Closure of the aortic and pulmonary valves.","B":"Opening of the aortic and pulmonary valves.","C":"Closure of the mitral and tricuspid valves.","D":"Opening of the mitral and tricuspid valves."},"answer":"C","why":"S1 occurs near onset of ventricular systole when rising ventricular pressure closes the AV valves and creates vibrations.","not":{"A":"Aortic and pulmonary closure generates S2.","B":"Semilunar opening does not generate the normal first sound.","D":"AV valve opening during filling is usually silent."}},{"id":"lt-circulation-1:020dca91","chapter":"heart-sounds","section":"2-why-does-s1-occur-before-s2","type":"mechanism","stem":"The second heart sound corresponds most closely to which transition?","options":{"A":"Atrial depolarisation to atrial systole.","B":"Atrial systole to passive ventricular filling.","C":"Ventricular filling to isovolumetric contraction.","D":"Ventricular ejection to isovolumetric relaxation."},"answer":"D","why":"S2 is produced by semilunar valve closure at the end of ejection, marking the onset of ventricular relaxation.","not":{"A":"Atrial events are not directly responsible for S2.","B":"AV valves are open during ordinary passive filling.","C":"S1 rather than S2 marks the beginning of isovolumetric contraction."}},{"id":"lt-circulation-1:a945c78b","chapter":"heart-sounds","section":"5-why-do-heart-sounds-change-in-loudness","type":"mechanism","stem":"Why may the aortic component of the second heart sound become more prominent in systemic hypertension?","options":{"A":"Brisk aortic valve closure under higher pressure.","B":"Late mitral valve closure during ventricular relaxation.","C":"Reduced pulmonary resistance delaying right ventricular ejection.","D":"Earlier tricuspid closure following atrial contraction."},"answer":"A","why":"Higher aortic pressure can produce a louder aortic component (A2) of S2 because aortic valve closure is more forceful.","not":{"B":"Mitral closure contributes to S1, not the aortic component of S2.","C":"Pulmonary resistance and right ventricular ejection primarily influence P2 timing.","D":"Tricuspid closure contributes to S1, not A2."}},{"id":"lt-circulation-1:0d1f2bab","chapter":"heart-sounds","section":"4-what-causes-s3-and-s4","type":"mechanism","stem":"A low-frequency third heart sound occurs in early diastole. What ventricular event coincides with it?","options":{"A":"Isovolumetric ventricular contraction.","B":"Rapid passive ventricular filling.","C":"Atrial depolarisation before systole.","D":"Opening of the aortic valve."},"answer":"B","why":"S3 occurs during rapid early-diastolic ventricular filling, as blood entering the chamber causes vibrations.","not":{"A":"Isovolumetric contraction occurs near S1.","C":"Atrial depolarisation precedes the atrial contribution later in diastole.","D":"Aortic valve opening occurs during ventricular systole."}},{"id":"lt-circulation-1:832d4b18","chapter":"heart-sounds","section":"4-what-causes-s3-and-s4","type":"mechanism","stem":"What produces an S4 in a patient with a stiff ventricle?","options":{"A":"Opening of the pulmonary valve against high pressure.","B":"Rapid early-diastolic filling before any atrial activity.","C":"Atrial contraction into a poorly compliant ventricle.","D":"Turbulence during systolic outflow across a normal aortic valve."},"answer":"C","why":"S4 is associated with late-diastolic atrial contraction into a stiff ventricle, which causes low-frequency vibrations.","not":{"A":"Pulmonary valve opening occurs in systole.","B":"Rapid passive filling is associated with S3 rather than S4.","D":"Systolic ejection turbulence describes a murmur, not S4."}},{"id":"lt-circulation-1:626d3fbb","chapter":"heart-sounds","section":"6-what-makes-a-murmur","type":"mechanism","stem":"Why might severe anaemia produce a cardiac flow murmur despite structurally normal valves?","options":{"A":"Anaemia markedly increases blood viscosity and suppresses flow.","B":"Reduced blood volume necessarily closes the aortic valve.","C":"Anaemia blocks the ventricular conduction system.","D":"Lower viscosity and increased flow favour turbulence."},"answer":"D","why":"Anaemia lowers viscosity and may increase cardiac output, raising the tendency to turbulent flow and a functional murmur.","not":{"A":"Anaemia decreases viscosity rather than increasing it.","B":"The murmur is not due to forced aortic valve closure.","C":"Conduction block is not the principal mechanism of flow murmurs."}},{"id":"lt-circulation-1:bc73362b","chapter":"heart-sounds","section":"7-predict-a-murmur-s-timing-without-memorising-a-list","type":"application","stem":"A harsh systolic murmur develops during blood ejection through a narrowed aortic valve. What mechanism explains it?","options":{"A":"Turbulent forward flow through a stenotic outflow orifice.","B":"Regurgitation through the mitral valve during diastole.","C":"Opening of the aortic valve during ventricular relaxation.","D":"Laminar blood flow through a normal-sized valve."},"answer":"A","why":"Aortic stenosis accelerates blood through a narrow outlet during systole, causing a turbulent ejection murmur.","not":{"B":"Mitral regurgitation usually occurs during systole, not diastole.","C":"The aortic valve opens when ventricular pressure exceeds aortic pressure in systole.","D":"Laminar flow through normal valves ordinarily produces no such murmur."}},{"id":"lt-circulation-1:57dca027","chapter":"heart-sounds","section":"8-where-do-we-listen-to-each-heart-valve","type":"anatomy","stem":"Where is the aortic valve normally auscultated most clearly?","options":{"A":"At the cardiac apex in the fifth left intercostal space.","B":"At the left lower sternal border near the fourth interspace.","C":"At the right second intercostal space near the sternum.","D":"At the left second intercostal space near the sternum."},"answer":"C","why":"The standard aortic area is the right second intercostal space at the sternal border, along the direction of transmitted sound.","not":{"A":"The apex is the usual mitral area.","B":"The left lower sternal border is associated with tricuspid sounds.","D":"The left second intercostal space is the usual pulmonary valve area, not the aortic area."}},{"id":"lt-circulation-1:8560af43","chapter":"cardiac-output","section":"1-what-is-cardiac-output-and-why-does-it-matter","type":"calculation","stem":"A patient's heart rate is 80 beats/min and stroke volume is 75 mL. What is cardiac output?","options":{"A":"4.8 L/min.","B":"6.0 L/min.","C":"7.5 L/min.","D":"8.0 L/min."},"answer":"B","why":"Cardiac output equals heart rate × stroke volume = 80 × 75 = 6000 mL/min or 6.0 L/min.","not":{"A":"4.8 L/min would correspond to 60 mL at 80 beats/min.","C":"7.5 L/min exceeds the calculated output.","D":"8.0 L/min assumes 100 mL per beat."}},{"id":"lt-circulation-1:e0697bb8","chapter":"cardiac-output","section":"2-why-can-changing-heart-rate-alter-cardiac-output","type":"mechanism","stem":"Why might increasing heart rate far above normal eventually reduce cardiac output?","options":{"A":"Contractility necessarily falls to zero.","B":"Diastolic time becomes longer and increases filling.","C":"The mitral valve is forced to remain permanently open.","D":"Shorter diastole reduces filling and stroke volume."},"answer":"D","why":"Extreme tachycardia shortens diastole, reduces filling and may decrease stroke volume enough to lower output.","not":{"A":"Contractility does not necessarily become zero.","B":"Diastole shortens markedly at high rates.","C":"Normal valves do not remain permanently open during extreme tachycardia."}},{"id":"lt-circulation-1:9fac2342","chapter":"cardiac-output","section":"3-what-determines-stroke-volume","type":"conceptual","stem":"Under the Frank–Starling law, why does greater ventricular filling strengthen systolic force?","options":{"A":"Stretch of myocardial fibres strengthens contraction.","B":"Higher afterload increases systemic venous return.","C":"Lower venous return increases sarcomere overlap.","D":"Reduced preload stimulates immediate calcium extrusion."},"answer":"A","why":"Within the physiological range, more end-diastolic filling stretches fibres and increases developed contraction force and stroke volume.","not":{"B":"Afterload is a separate determinant of ejection.","C":"Lower venous return reduces ventricular fibre stretch.","D":"Calcium extrusion is related to relaxation, not the primary stretch mechanism."}},{"id":"lt-circulation-1:46c6ed8d","chapter":"cardiac-output","section":"5-how-do-we-read-frank-starling-curves","type":"graph-interpretation","stem":"Two Frank–Starling curves are plotted against identical end-diastolic volumes. What does an upward shift of the entire curve usually indicate?","options":{"A":"Greater afterload alone with unchanged contractility.","B":"Aortic valve closure earlier in systole.","C":"Greater contractility at the same preload.","D":"Lower force development at every fibre length."},"answer":"C","why":"Positive inotropy raises stroke volume or output at the same filling level, shifting the Frank–Starling function upward.","not":{"A":"Higher afterload tends to impair ejection.","B":"Valve closure timing is not the definition of an upward Starling curve.","D":"Lower force would shift the curve downward, not upward."}},{"id":"lt-circulation-1:703f5aa6","chapter":"cardiac-output","section":"6-what-raises-or-lowers-end-diastolic-volume","type":"application","stem":"A patient develops cardiac tamponade. Why can stroke volume fall despite a normal blood volume?","options":{"A":"Tamponade increases functional ventricular compliance.","B":"High pericardial pressure restricts ventricular filling.","C":"Tamponade directly raises venous return above normal.","D":"The aortic valve cannot open due solely to a high heart rate."},"answer":"B","why":"Elevated intrapericardial pressure limits end-diastolic filling and preload, reducing stroke volume. The restricted ventricular volume prevents an adequate Frank–Starling response.","not":{"A":"Tamponade reduces the ability of ventricles to expand.","C":"Venous return and effective filling become impaired.","D":"Valvular opening depends on pressure, but reduced preload is the central problem."}},{"id":"lt-circulation-1:c34b2df2","chapter":"cardiac-output","section":"6-what-raises-or-lowers-end-diastolic-volume","type":"application","stem":"After standing suddenly, a healthy person has a transient fall in end-diastolic volume. Which cause is most direct?","options":{"A":"Increased atrial contraction generating excess preload.","B":"Increased circulating red-cell mass.","C":"Greater coronary artery blood flow.","D":"Venous pooling reducing return to the heart."},"answer":"D","why":"Gravity shifts blood into compliant leg veins, decreasing venous return and end-diastolic filling. Stroke volume then falls transiently by Frank–Starling physiology.","not":{"A":"Atrial contraction tends to increase rather than reduce filling.","B":"Red-cell mass does not change in seconds with posture.","C":"Coronary flow does not explain the immediate preload decline."}},{"id":"lt-circulation-1:461edc93","chapter":"cardiac-output","section":"7-what-changes-contractility","type":"mechanism","stem":"Why can xanthines such as theophylline produce a positive inotropic effect at the signalling level described in the lecture?","options":{"A":"They reduce the breakdown of intracellular cAMP.","B":"They directly prevent L-type calcium-channel opening.","C":"They accelerate the breakdown of intracellular cAMP.","D":"They permanently suppress myocardial beta-1 receptors."},"answer":"A","why":"The lecture describes phosphodiesterase inhibition by xanthines, which slows cAMP breakdown; increased cAMP-dependent signalling can enhance myocardial calcium handling and contractility.","not":{"B":"Reducing calcium entry would tend to depress rather than enhance contraction.","C":"Faster cAMP degradation would reduce this positive inotropic pathway.","D":"Blocking beta-1 signalling would generally reduce adrenergic inotropy."}},{"id":"lt-circulation-1:f6ae8746","chapter":"cardiac-output","section":"7-what-changes-contractility","type":"comparison","stem":"Which condition is most likely to depress myocardial contractility rather than enhance it?","options":{"A":"Acute beta-1 adrenergic activation.","B":"Raised circulating catecholamines.","C":"Severe hypoxia with acidosis.","D":"Increased calcium availability in cells."},"answer":"C","why":"Severe hypoxia and acidosis impair myocardial function and are listed as causes of depressed inotropy.","not":{"A":"Beta-1 activation generally enhances contractility.","B":"Catecholamines usually raise inotropy initially.","D":"Increased cytosolic calcium generally enhances contraction."}},{"id":"lt-circulation-1:936dd9a9","chapter":"cardiac-output","section":"8-how-do-preload-afterload-and-inotropy-differ-in-real-situations","type":"mechanism","stem":"A patient's blood pressure rises markedly with no initial change in contractility or preload. What happens to ventricular afterload?","options":{"A":"It falls as the aortic pressure increases.","B":"Higher arterial pressure opposes ventricular ejection.","C":"It becomes identical to ventricular end-diastolic volume.","D":"It disappears once the semilunar valves open."},"answer":"B","why":"Higher systemic arterial pressure increases the pressure the left ventricle must develop to eject, raising afterload.","not":{"A":"The pressure burden rises rather than falls.","C":"Afterload is resistance/pressure load, not a volume.","D":"Afterload persists throughout ejection."}},{"id":"lt-circulation-1:4a7daf45","chapter":"cardiac-output","section":"9-what-happens-to-cardiac-output-during-exercise-and-other-states","type":"mechanism","stem":"During graded exercise, which combination helps increase cardiac output?","options":{"A":"Greater vagal activity and smaller stroke volume.","B":"Reduced sympathetic drive and greater afterload.","C":"Slower pacemaking and lower venous return.","D":"Higher rate, contractility and venous return."},"answer":"D","why":"Sympathetic drive raises heart rate and contractility while muscle pumping supports venous return, enabling higher cardiac output.","not":{"A":"Vagal dominance would tend to slow the heart.","B":"Reduced sympathetic drive does not explain exercise output.","C":"Exercise generally increases rather than suppresses cardiac pumping."}},{"id":"lt-circulation-1:dcf16280","chapter":"co-measurement","section":"2-fick-s-principle-working-out-flow-from-oxygen-use","type":"calculation","stem":"Whole-body oxygen use is 250 mL/min. Arterial and mixed venous oxygen contents are 200 and 150 mL/L. What is Fick cardiac output?","options":{"A":"5.0 L/min.","B":"3.0 L/min.","C":"10.0 L/min.","D":"12.5 L/min."},"answer":"A","why":"Fick cardiac output = oxygen consumption ÷ arteriovenous O₂ content difference = 250 ÷ (200 − 150) = 5 L/min.","not":{"B":"3 L/min would require a larger oxygen content difference.","C":"10 L/min would require only 25 mL/L extraction.","D":"12.5 L/min corresponds to only 20 mL/L extraction."}},{"id":"lt-circulation-1:6109249f","chapter":"co-measurement","section":"2-fick-s-principle-working-out-flow-from-oxygen-use","type":"mechanism","stem":"What conservation principle underlies Fick measurement of cardiac output?","options":{"A":"Venous oxygen usually matches arterial oxygen content.","B":"The heart produces all consumed oxygen internally.","C":"Oxygen use equals flow × arterial–venous oxygen difference.","D":"Oxygen consumption is independent of blood flow and extraction."},"answer":"C","why":"By mass balance, oxygen uptake across lungs and consumption by tissues equal cardiac output multiplied by arterial–venous oxygen content difference.","not":{"A":"Tissues extract oxygen, so venous content is generally lower.","B":"The body consumes oxygen but does not produce it.","D":"Extraction and flow together determine total oxygen consumption."}},{"id":"lt-circulation-1:32503902","chapter":"co-measurement","section":"3-where-do-the-oxygen-measurements-come-from","type":"methods","stem":"In a whole-body Fick measurement, which blood should the return-side oxygen sample represent?","options":{"A":"Oxygenated blood in a systemic artery.","B":"Mixed venous blood entering the lungs.","C":"Blood in a single peripheral venule.","D":"Capillary blood from active skeletal muscle only."},"answer":"B","why":"A mixed venous sample from pulmonary artery reflects oxygen after extraction across the whole body.","not":{"A":"Arterial blood provides the other concentration in the equation.","C":"One local vein does not represent average whole-body extraction.","D":"Active muscle has unusually high local extraction and can misrepresent the body."}},{"id":"lt-circulation-1:6c25506c","chapter":"co-measurement","section":"5-what-does-it-mean-for-the-heart-to-perform-work","type":"conceptual","stem":"What does the mechanical stroke work of a ventricle represent?","options":{"A":"Electrical energy in the SA node over one minute.","B":"The number of coronary capillaries recruited.","C":"Heart rate multiplied by body surface area.","D":"Ventricular pressure–volume work per beat."},"answer":"D","why":"The ventricle performs pressure–volume work as it ejects stroke volume against an arterial pressure load.","not":{"A":"Pacemaker electrical energy is not mechanical stroke work.","B":"Capillary recruitment affects supply, not the definition of work.","C":"Heart rate and surface area do not directly define mechanical work."}},{"id":"lt-circulation-1:00b18d03","chapter":"co-measurement","section":"7-why-does-pressure-loading-increase-the-heart-s-oxygen-demand","type":"mechanism","stem":"Why does sustained systemic hypertension tend to raise myocardial oxygen demand?","options":{"A":"The ventricle must generate higher pressure for ejection.","B":"Aortic pressure removes myocardial wall tension.","C":"Coronary venous oxygen content necessarily becomes arterial.","D":"The left ventricle stops contracting during systole."},"answer":"A","why":"Higher arterial pressure increases ventricular pressure work and wall stress, requiring more oxygen for force generation.","not":{"B":"Higher afterload generally increases wall stress.","C":"Coronary oxygen extraction remains substantial.","D":"The myocardium continues to contract against the higher load."}},{"id":"lt-circulation-1:f4eb6fa9","chapter":"hemodynamics","section":"1-what-propels-blood-around-the-circulation","type":"mechanism","stem":"What helps maintain forward systemic arterial flow between heartbeats?","options":{"A":"The diaphragm pumps blood through the aorta during inspiration.","B":"The elastic recoil of large arteries sustains diastolic flow.","C":"Capillaries generate contractions that propel blood upstream.","D":"Venous valves directly generate aortic pressure."},"answer":"B","why":"Elastic arteries stretch during systole and recoil during diastole, smoothing pulsatile ejection into continuous downstream flow.","not":{"A":"Respiratory movement mainly assists venous return.","C":"Capillaries lack the pumping muscle required to drive systemic flow.","D":"Venous valves prevent backflow but do not create aortic pressure."}},{"id":"lt-circulation-1:55c3e4eb","chapter":"hemodynamics","section":"2-what-actually-determines-flow","type":"calculation","stem":"A vascular bed has a pressure difference of 80 mmHg and resistance of 20 mmHg·min/L. What is its flow?","options":{"A":"2 L/min.","B":"3 L/min.","C":"4 L/min.","D":"8 L/min."},"answer":"C","why":"Flow equals pressure difference divided by resistance: 80/20 = 4 L/min. Increasing resistance with the same pressure difference would lower flow.","not":{"A":"Two L/min would correspond to resistance of 40.","B":"Three L/min does not fit the given ratio.","D":"Eight L/min would correspond to resistance of 10."}},{"id":"lt-circulation-1:1b8b6975","chapter":"hemodynamics","section":"3-why-do-different-vessels-have-different-roles","type":"conceptual","stem":"Which vessel class offers the greatest adjustable resistance to systemic tissue blood flow?","options":{"A":"Arterioles.","B":"Large veins.","C":"Capillaries.","D":"The venae cavae."},"answer":"A","why":"Arteriolar smooth muscle changes diameter markedly, allowing tissues to regulate resistance and flow. A small diameter change produces a large resistance change through the fourth-power relationship.","not":{"B":"Large veins chiefly serve as capacitance vessels.","C":"Capillaries mainly exchange materials and have no continuous smooth-muscle coat.","D":"The venae cavae are low-resistance return conduits."}},{"id":"lt-circulation-1:d058f431","chapter":"hemodynamics","section":"4-why-is-blood-velocity-lowest-in-capillaries","type":"mechanism","stem":"Why is average linear blood velocity lowest in systemic capillaries?","options":{"A":"They have the largest diameter individually.","B":"Their blood pressure equals aortic pressure.","C":"Blood becomes denser within every capillary.","D":"The largest combined cross-sectional area."},"answer":"D","why":"At a given total flow, velocity equals flow divided by total cross-sectional area; capillaries have the largest summed area.","not":{"A":"Individual capillary diameters are very small.","B":"Capillary pressure is much lower than aortic pressure.","C":"Blood density differences do not explain the major velocity drop."}},{"id":"lt-circulation-1:3b765b14","chapter":"hemodynamics","section":"5-laminar-flow-turbulence-and-reynolds-number","type":"mechanism","stem":"For steady laminar flow through a straight tube, where is linear velocity highest?","options":{"A":"At the endothelial wall.","B":"At the vessel centre.","C":"Uniformly across the lumen.","D":"At the outer plasma layer."},"answer":"B","why":"Viscous drag slows flow near the wall; a parabolic velocity profile has its greatest velocity near the centre.","not":{"A":"The no-slip boundary makes velocity near the wall approach zero.","C":"Laminar flow has a radial velocity gradient.","D":"The plasma layer adjacent to the wall is not the maximum-velocity region."}},{"id":"lt-circulation-1:a0f0ceca","chapter":"hemodynamics","section":"5-laminar-flow-turbulence-and-reynolds-number","type":"application","stem":"At unchanged blood density, vessel diameter and viscosity, what happens to Reynolds number if average blood velocity doubles?","options":{"A":"It doubles.","B":"It falls to one-half.","C":"It rises fourfold.","D":"It remains constant."},"answer":"A","why":"Reynolds number is proportional to blood velocity when density, viscosity and vessel diameter remain fixed. Doubling velocity therefore doubles Reynolds number and makes turbulence more likely.","not":{"B":"A halving would require the velocity-dependent term to decrease.","C":"Velocity enters the Reynolds relation linearly, not as its square.","D":"Reynolds number changes when velocity changes at fixed other variables."}},{"id":"lt-circulation-1:bbf56376","chapter":"hemodynamics","section":"6-why-is-vessel-radius-such-a-powerful-determinant-of-flow","type":"calculation","stem":"An arteriole's radius falls to half its previous value; other variables stay constant. How does its resistance change?","options":{"A":"By a factor of 2.","B":"By a factor of 4.","C":"By a factor of 8.","D":"A factor of 16."},"answer":"D","why":"Poiseuille resistance varies with 1/r⁴; halving radius raises resistance by 2⁴ = 16. The radius effect is disproportionately large because it is raised to the fourth power.","not":{"A":"A doubling assumes linear radius dependence.","B":"Fourfold assumes a square-law dependence.","C":"Eightfold assumes a cubic rather than fourth-power relation."}},{"id":"lt-circulation-1:30705b00","chapter":"hemodynamics","section":"7-viscosity-haematocrit-and-blood-cells","type":"application","stem":"A patient with marked polycythaemia has elevated haematocrit. What is the expected direct effect on systemic flow resistance?","options":{"A":"Lower viscosity and lower total vascular resistance.","B":"Lower viscosity and higher resistance.","C":"Higher viscosity and higher resistance.","D":"Higher viscosity and lower resistance."},"answer":"C","why":"More red cells increase blood viscosity and consequently vascular resistance, raising the heart's workload.","not":{"A":"Both properties generally increase, not decrease.","B":"Lower viscosity does not follow from higher haematocrit.","D":"Higher viscosity raises resistance rather than lowering it."}},{"id":"lt-circulation-1:e3d81eda","chapter":"hemodynamics","section":"9-how-can-blood-flow-be-measured","type":"methods","stem":"What principle allows an electromagnetic flowmeter to determine vascular flow?","options":{"A":"Moving conductive blood induces voltage in a magnetic field.","B":"An oxygen content difference equals flow independent of metabolism.","C":"A cuff detects the onset of venous Korotkoff sounds.","D":"A radioactive tracer measures only red-cell lifespan."},"answer":"A","why":"Conducting blood moving through a magnetic field induces a voltage that can be used to estimate its velocity and flow.","not":{"B":"That describes neither the electromagnetic principle nor Fick correctly.","C":"Korotkoff sounds estimate arterial blood pressure, not direct flow.","D":"Tracer approaches are distinct from electromagnetic flow measurement."}},{"id":"lt-circulation-1:51b5ef39","chapter":"hemodynamics","section":"10-why-can-veins-hold-more-blood-than-arteries","type":"comparison","stem":"Compared with a large artery, why can a large vein store more blood for a small rise in pressure?","options":{"A":"Venous walls contain more elastic recoil tissue than aorta.","B":"Veins have high compliance and distensible walls.","C":"Venous vessels are made mostly of cardiac muscle.","D":"Venous pressure generally exceeds aortic systolic pressure."},"answer":"B","why":"Veins have thin distensible walls and high compliance, so volume changes greatly for modest pressure changes.","not":{"A":"Large arteries have substantial elastic tissue; veins serve mainly as capacitance vessels.","C":"Veins are not cardiac muscle.","D":"Systemic venous pressure is much lower than aortic systolic pressure; compliance concerns volume change per unit pressure change."}},{"id":"lt-circulation-1:56e11e13","chapter":"blood-pressure","section":"2-why-doesn-t-blood-stop-moving-during-diastole","type":"mechanism","stem":"During ventricular diastole, what would an increase in peripheral resistance do to the rate of aortic pressure decline if compliance were unchanged?","options":{"A":"Speed the decline by increasing downstream runoff.","B":"Leave the decline unaffected by downstream resistance.","C":"Slow the decline by reducing downstream runoff.","D":"Reverse arterial flow from capillaries toward the aorta."},"answer":"C","why":"Greater downstream resistance reduces diastolic runoff from the elastic arterial reservoir; at unchanged compliance, aortic pressure falls more slowly.","not":{"A":"Greater resistance normally reduces runoff rather than increasing it.","B":"Diastolic decay depends in part on resistance and arterial compliance.","D":"Higher resistance slows forward runoff but does not reverse normal arterial flow."}},{"id":"lt-circulation-1:029ffabb","chapter":"blood-pressure","section":"4-what-is-pulse-pressure","type":"calculation","stem":"A blood-pressure reading is 132/84 mmHg. What is the pulse pressure?","options":{"A":"36 mmHg.","B":"40 mmHg.","C":"44 mmHg.","D":"48 mmHg."},"answer":"D","why":"Pulse pressure equals systolic minus diastolic: 132 − 84 = 48 mmHg. It measures the pressure swing between systole and diastole.","not":{"A":"Thirty-six is below the arithmetic difference.","B":"Forty does not equal 132 minus 84.","C":"Forty-four is four mmHg below the difference."}},{"id":"lt-circulation-1:52078de5","chapter":"blood-pressure","section":"5-what-is-mean-arterial-pressure-and-why-isn-t-it-simply-the-midpoint","type":"calculation","stem":"For a resting pressure of 120/75 mmHg, what is the approximate mean arterial pressure?","options":{"A":"90 mmHg.","B":"98 mmHg.","C":"103 mmHg.","D":"110 mmHg."},"answer":"A","why":"MAP ≈ diastolic pressure + one-third pulse pressure = 75 + (45/3) = 90 mmHg.","not":{"B":"Ninety-eight is above the usual approximation.","C":"One hundred three ignores the longer duration of diastole.","D":"One hundred ten is closer to systolic pressure than the time-weighted mean."}},{"id":"lt-circulation-1:9c77cd79","chapter":"blood-pressure","section":"6-why-does-measured-bp-depend-on-whether-the-arm-is-above-or-below-the-heart","type":"application","stem":"A sphygmomanometer cuff is held substantially below heart level. How is its pressure reading affected by gravity?","options":{"A":"It reads falsely low because of reduced hydrostatic pressure.","B":"It reads falsely high because of added hydrostatic pressure.","C":"It is unaffected because arterial vessels have valves.","D":"It measures venous instead of arterial pressure."},"answer":"B","why":"A measurement site below the heart has extra hydrostatic pressure, making the reading higher than heart-level pressure.","not":{"A":"Above-heart placement would give a falsely lower reading.","C":"Arteries do not have the venous valves needed to cancel gravity.","D":"The cuff still estimates arterial pressure."}},{"id":"lt-circulation-1:5679841e","chapter":"blood-pressure","section":"7-how-does-a-cuff-and-stethoscope-reveal-systolic-and-diastolic-pressure","type":"mechanism","stem":"During manual auscultatory BP measurement, what does the first clear Korotkoff sound indicate?","options":{"A":"Diastolic pressure at complete flow cessation.","B":"The mean arterial pressure by definition.","C":"Systolic pressure as turbulent flow first appears.","D":"The pulse pressure as the cuff first touches the arm."},"answer":"C","why":"The first Korotkoff sounds emerge when cuff pressure falls just below systolic arterial pressure and blood begins passing intermittently.","not":{"A":"Diastolic pressure is commonly estimated when sounds disappear.","B":"The first sound corresponds to systolic, not mean, pressure.","D":"Pulse pressure requires both systolic and diastolic values."}},{"id":"lt-circulation-1:e3914fbd","chapter":"blood-pressure","section":"8-how-should-bp-actually-be-measured-accurately","type":"application","stem":"A cuff that is far too small is used on a large upper arm. Which measurement error is likely?","options":{"A":"Falsely low BP from excessive arterial unloading.","B":"No systematic effect on cuff pressure.","C":"Only diastolic pressure becomes unmeasurable.","D":"An undersized cuff gives a falsely high reading."},"answer":"D","why":"An undersized cuff transmits pressure poorly around a large arm and commonly overestimates measured pressure.","not":{"A":"A small cuff usually overestimates rather than underestimates BP.","B":"Cuff size materially affects readings.","C":"Both systolic and diastolic measurements may be distorted."}},{"id":"lt-circulation-1:c183f4e2","chapter":"blood-pressure","section":"9-why-does-pressure-decrease-as-blood-travels-through-the-circulation","type":"mechanism","stem":"Where is the largest controllable fall in systemic vascular pressure normally produced?","options":{"A":"Across resistance arterioles.","B":"Across the venae cavae.","C":"Across large elastic arteries.","D":"Within the right atrium alone."},"answer":"A","why":"Small arteries and arterioles provide substantial resistance, producing a major pressure drop from arterial to capillary levels.","not":{"B":"Large veins carry blood at low pressure and resistance.","C":"Large elastic arteries conduct flow with relatively small resistance.","D":"Right atrial pressure is low but does not create the main distributed arterial drop."}},{"id":"lt-circulation-1:a2216e03","chapter":"pulses","section":"1-what-is-an-arterial-pulse","type":"conceptual","stem":"What is detected by the fingers when palpating the radial pulse?","options":{"A":"Individual red cells striking the wrist.","B":"An arterial wall-distension pressure wave.","C":"A direct pulse of venous blood into the radial artery.","D":"An electrical signal passing along the endothelium."},"answer":"B","why":"Each ventricular ejection creates an arterial pressure/distension wave that travels along the arteries. This pressure wave moves faster than the bulk blood itself.","not":{"A":"Red cells are not separately felt during palpation.","C":"Venous blood does not directly pulse into systemic arteries.","D":"The palpable pulse is mechanical rather than an electrical conduction wave."}},{"id":"lt-circulation-1:7331e73b","chapter":"pulses","section":"4-why-are-the-a-c-and-v-waves-separated-by-x-and-y-descents","type":"interpretation","stem":"What produces the 'a' wave in a normal jugular venous pulse tracing?","options":{"A":"Right atrial contraction.","B":"Aortic valve opening.","C":"Rapid ventricular ejection.","D":"Pulmonary valve closure."},"answer":"A","why":"The a wave reflects the rise in right atrial pressure during atrial systole. It occurs immediately before right ventricular contraction.","not":{"B":"Aortic opening is a left ventricular outflow event.","C":"Ventricular ejection is not the primary a-wave mechanism.","D":"Pulmonary closure occurs near end systole."}},{"id":"lt-circulation-1:4e5ab9bd","chapter":"pulses","section":"4-why-are-the-a-c-and-v-waves-separated-by-x-and-y-descents","type":"interpretation","stem":"The jugular venous 'c' wave is chiefly linked to which event?","options":{"A":"Passive systemic venous filling late in systole.","B":"Rapid emptying of the right atrium.","C":"Systolic bulging of the tricuspid valve.","D":"Right atrial contraction immediately before QRS."},"answer":"C","why":"Early right ventricular contraction can bulge the shut tricuspid valve toward the right atrium, contributing to the c wave.","not":{"A":"Venous filling behind a closed tricuspid valve makes the v wave.","B":"Rapid atrial emptying contributes to the y descent.","D":"Right atrial systole generates the a wave."}},{"id":"lt-circulation-1:e08bc63a","chapter":"pulses","section":"4-why-are-the-a-c-and-v-waves-separated-by-x-and-y-descents","type":"interpretation","stem":"What does the normal jugular venous 'v' wave mainly represent?","options":{"A":"Closure of the pulmonary semilunar valve.","B":"Right atrial electrical depolarisation.","C":"Completion of left ventricular ejection.","D":"Atrial filling while tricuspid is closed."},"answer":"D","why":"Systemic venous return fills the right atrium during ventricular systole while the tricuspid valve remains closed, creating the v wave.","not":{"A":"Pulmonary valve closure is near S2.","B":"Atrial depolarisation precedes the a wave.","C":"The v wave is defined by right atrial filling rather than aortic ejection."}},{"id":"lt-circulation-1:3659299c","chapter":"pulses","section":"4-why-are-the-a-c-and-v-waves-separated-by-x-and-y-descents","type":"comparison","stem":"What distinguishes the normal x descent from the y descent in a JVP trace?","options":{"A":"x: atrial relaxation; y: emptying through the open tricuspid.","B":"x: atrial contraction; y: ventricular isovolumetric contraction.","C":"x: ventricular ejection; y: pulmonary arterial recoil.","D":"x: aortic valve opening; y: mitral valve closure."},"answer":"A","why":"The x descent reflects atrial relaxation and downward tricuspid movement; the y descent follows tricuspid opening as blood empties rapidly.","not":{"B":"Atrial contraction creates the a wave.","C":"Both descents reflect right atrial pressure changes rather than the proposed events.","D":"Left-heart valve events do not define these JVP descents."}},{"id":"lt-circulation-1:96876464","chapter":"pulses","section":"7-which-abnormal-jvp-waves-are-most-important","type":"application","stem":"A patient with severe tricuspid regurgitation has a prominent systolic jugular venous wave. Which wave becomes especially large?","options":{"A":"a wave.","B":"v wave.","C":"x descent.","D":"y descent."},"answer":"B","why":"Tricuspid regurgitation sends systolic flow back into the right atrium and systemic veins, producing a large v or fused c-v wave.","not":{"A":"The a wave reflects atrial contraction and is not the characteristic regurgitant finding.","C":"The x descent may be blunted rather than unusually enlarged.","D":"The y descent is an emptying phase and does not represent systolic backflow."}},{"id":"lt-circulation-1:6737c212","chapter":"pulses","section":"7-which-abnormal-jvp-waves-are-most-important","type":"application","stem":"In complete AV dissociation, the right atrium occasionally contracts against a closed tricuspid valve. What JVP abnormality may follow?","options":{"A":"Loss of all visible venous pulsations.","B":"A steady nonpulsatile jugular column.","C":"Intermittent cannon a waves.","D":"An isolated giant v wave after every beat."},"answer":"C","why":"Unsynchronised atrial contraction against a shut AV valve can produce large intermittent cannon a waves.","not":{"A":"Venous pulsations can persist despite AV block.","B":"Atrial contractions still cause pressure variations.","D":"Giant v waves primarily suggest tricuspid regurgitation."}},{"id":"lt-circulation-1:52e95cca","chapter":"venous-return","section":"2-why-are-veins-called-capacitance-vessels","type":"mechanism","stem":"A sudden increase in sympathetic venous tone can support cardiac output mainly through which immediate effect?","options":{"A":"It dilates veins, increasing blood stored in the limbs.","B":"It creates new circulating plasma within seconds.","C":"Venoconstriction shifts stored blood centrally.","D":"It closes arteriolar valves and stops peripheral outflow."},"answer":"C","why":"Sympathetic venoconstriction reduces the capacity of the venous reservoir and shifts stored blood toward the heart, supporting venous return and end-diastolic filling.","not":{"A":"Venodilation generally increases peripheral capacitance and pooling.","B":"Venoconstriction redistributes existing blood rather than rapidly generating plasma.","D":"Systemic arterioles have no valves that close with sympathetic stimulation."}},{"id":"lt-circulation-1:b2a84f6b","chapter":"venous-return","section":"3-what-pressure-actually-drives-venous-return","type":"mechanism","stem":"Which pressure difference primarily drives blood back to the right atrium from the body?","options":{"A":"Left ventricular systolic minus aortic diastolic pressure.","B":"Pulmonary venous minus pulmonary capillary pressure.","C":"Aortic systolic minus right ventricular systolic pressure.","D":"Systemic filling pressure minus right atrial pressure."},"answer":"D","why":"Venous return depends on the upstream systemic filling pressure relative to right atrial pressure and the resistance to venous return.","not":{"A":"That difference is a pulse-pressure-related comparison.","B":"Pulmonary venous pressure does not define systemic venous return.","C":"Aortic-right ventricular systolic pressure is not the venous return driving gradient."}},{"id":"lt-circulation-1:83363b77","chapter":"venous-return","section":"4-how-do-the-skeletal-muscle-pump-and-venous-valves-work","type":"mechanism","stem":"What mechanical advantage do venous valves provide to a contracting calf-muscle pump?","options":{"A":"They prevent backward blood movement during muscular compression.","B":"They directly increase the oxygen-carrying capacity of venous blood.","C":"They eliminate hydrostatic pressure from the entire limb.","D":"They produce sympathetic impulses to constrict arteries."},"answer":"A","why":"Muscle contraction compresses deep veins, and valves constrain flow toward the heart rather than allowing reflux.","not":{"B":"Valves do not alter haemoglobin or oxygen capacity.","C":"Gravity remains present even when valves assist drainage.","D":"The valve mechanism is mechanical, not an autonomic trigger."}},{"id":"lt-circulation-1:2ff9bffe","chapter":"venous-return","section":"5-how-does-breathing-help-venous-return","type":"mechanism","stem":"How does normal inspiration tend to assist systemic venous return?","options":{"A":"It increases right atrial pressure and reduces abdominal pressure.","B":"Lower chest pressure draws venous blood toward the heart.","C":"It closes all systemic venous valves simultaneously.","D":"It increases peripheral venous capacitance until return stops."},"answer":"B","why":"Inspiration decreases intrathoracic pressure and promotes a pressure gradient drawing blood from peripheral veins to the thorax.","not":{"A":"Lower rather than higher thoracic pressure assists inflow.","C":"Venous valves do not all close in inspiration.","D":"Return is generally supported rather than abolished."}},{"id":"lt-circulation-1:7ab62862","chapter":"venous-return","section":"6-what-does-central-venous-pressure-tell-us","type":"application","stem":"A patient's right ventricular pumping fails and right atrial pressure rises. Which consequence is most likely?","options":{"A":"A larger pressure gradient for systemic venous return.","B":"Reduced congestion in peripheral systemic veins.","C":"Reduced venous return gradient with congestion.","D":"Complete disappearance of the jugular venous pulse."},"answer":"C","why":"Higher right atrial pressure opposes venous return and transmits backward into systemic veins, causing congestion.","not":{"A":"Higher right atrial pressure reduces the upstream-to-atrial gradient.","B":"Elevated atrial pressure tends to increase congestion.","D":"JVP often becomes elevated rather than disappearing."}},{"id":"lt-circulation-1:fa62c5a4","chapter":"venous-return","section":"7-what-happens-to-veins-in-the-head-when-standing","type":"application","stem":"Why are superficial neck veins often less distended in a healthy person who stands upright?","options":{"A":"Venous pressure decreases above the heart.","B":"The venae cavae reverse their direction of blood flow.","C":"Systemic venous pressure exceeds aortic systolic pressure.","D":"The skull's arteries pull venous valves fully open."},"answer":"A","why":"Gravity lowers venous pressure above the heart; collapsible superficial veins can flatten at low transmural pressure.","not":{"B":"Venous return does not normally reverse direction.","C":"Systemic venous pressure remains far below aortic systolic pressure.","D":"Arterial flow does not open venous valves in the neck."}},{"id":"lt-circulation-1:6872dc57","chapter":"microcirculation","section":"1-why-is-the-microcirculation-necessary","type":"conceptual","stem":"What is the primary functional importance of the extensive capillary network?","options":{"A":"It maintains the highest blood velocity in the circulation.","B":"It generates most of the arterial pressure.","C":"It stores nearly all circulating blood volume.","D":"It provides a large surface for tissue exchange."},"answer":"D","why":"Numerous small capillaries provide enormous exchange area and low velocity, favouring nutrient and waste movement.","not":{"A":"Average velocity is low because total capillary cross-section is large.","B":"Arterioles supply much of controllable resistance.","C":"Veins, not capillaries, hold the major blood reservoir."}},{"id":"lt-circulation-1:7ef9586a","chapter":"microcirculation","section":"3-how-do-substances-actually-cross-the-capillary-wall","type":"mechanism","stem":"Which mechanism supplies a respiratory gas from capillary blood to nearby tissues?","options":{"A":"Bulk movement of intact plasma proteins.","B":"Oxygen diffusing down its pressure gradient.","C":"Active pumping of intact red cells through the wall.","D":"Lymphatic return of oxygenated interstitial fluid."},"answer":"B","why":"Oxygen is small and diffusible, so it crosses membranes down its partial-pressure gradient toward metabolising tissue.","not":{"A":"Oxygen transfer does not require bulk plasma protein movement.","C":"Red cells remain inside ordinary capillaries.","D":"Lymphatics return fluid and proteins, not the primary oxygen supply."}},{"id":"lt-circulation-1:6b28902f","chapter":"microcirculation","section":"4-what-decides-which-capillaries-receive-more-blood","type":"mechanism","stem":"A working tissue releases vasodilator metabolites around its microvessels. What adjustment most directly raises local perfusion?","options":{"A":"Upstream arteriolar and precapillary relaxation.","B":"Tightening of upstream arterioles to prevent blood entry.","C":"Increased viscosity in the tissue's capillary blood.","D":"Complete collapse of capillary exchange surfaces."},"answer":"A","why":"Metabolic vasodilators relax resistance vessels and recruit perfused capillaries, improving delivery to active tissue.","not":{"B":"Constriction would reduce perfusion.","C":"Greater viscosity would increase resistance.","D":"Capillary collapse would worsen nutrient exchange."}},{"id":"lt-circulation-1:60b647f9","chapter":"microcirculation","section":"5-why-does-fluid-leave-capillaries-even-when-protein-stays-in-blood","type":"mechanism","stem":"Increasing capillary hydrostatic pressure while other Starling forces stay unchanged tends to produce what?","options":{"A":"Decreased outward fluid filtration.","B":"Increased plasma oncotic attraction.","C":"More fluid filtration into tissues.","D":"Reversal of lymphatic flow."},"answer":"C","why":"A higher capillary hydrostatic force favours filtration across the microvascular wall toward tissue. Raising venous pressure is one way to produce this hydrostatic change.","not":{"A":"The pressure favours outward, not reduced, filtration.","B":"Plasma oncotic pressure does not automatically increase.","D":"Lymphatic flow generally responds to excess tissue fluid rather than reversing."}},{"id":"lt-circulation-1:0f0d62d2","chapter":"microcirculation","section":"5-why-does-fluid-leave-capillaries-even-when-protein-stays-in-blood","type":"comparison","stem":"At an otherwise unchanged capillary, how would increased interstitial protein concentration affect fluid movement?","options":{"A":"It strengthens plasma oncotic pressure, reducing filtration.","B":"It lowers capillary hydrostatic pressure, opposing filtration.","C":"It increases protein attraction into the blood compartment.","D":"It strengthens the outward oncotic force favouring filtration."},"answer":"D","why":"More interstitial protein increases interstitial colloid osmotic pressure, tending to pull fluid outward from the capillary and increase filtration.","not":{"A":"Plasma protein concentration is held constant; the changed force is interstitial.","B":"A change in interstitial protein does not directly lower capillary pressure.","C":"Increased proteins outside the capillary attract rather than remove interstitial water."}},{"id":"lt-circulation-1:b96b83cc","chapter":"microcirculation","section":"6-classic-starling-model-versus-revised-understanding","type":"conceptual","stem":"Which statement best reflects the updated interpretation of capillary fluid balance?","options":{"A":"Most capillaries continuously reabsorb nearly all filtered fluid at their venous ends.","B":"The glycocalyx regulates filtration; lymph returns excess fluid.","C":"Interstitial proteins do not affect exchange at any capillary.","D":"Lymphatic vessels play no role when hydrostatic pressure is normal."},"answer":"B","why":"The revised Starling model includes the glycocalyx and emphasises that sustained net filtration is normally cleared by lymphatics.","not":{"A":"The classical arterial filtration–venous reabsorption picture overstates sustained reabsorption.","C":"Protein distributions can influence effective oncotic gradients.","D":"Lymphatic return remains vital even at normal pressures."}},{"id":"lt-circulation-1:2d8be0e5","chapter":"microcirculation","section":"7-what-changes-microvascular-filtration-or-permeability","type":"mechanism","stem":"A local inflammatory mediator increases postcapillary venular permeability. What occurs?","options":{"A":"More protein and water can escape, promoting tissue swelling.","B":"The vascular wall becomes impermeable to water.","C":"The plasma protein concentration increases within the vessel.","D":"Capillary filtration stops until arterial pressure rises."},"answer":"A","why":"Higher permeability permits protein extravasation and fluid movement, weakening oncotic retention and promoting oedema.","not":{"B":"Inflammation generally increases rather than abolishes permeability.","C":"Protein leakage tends to lower intravascular protein in the affected region.","D":"Fluid escape is promoted, not stopped."}},{"id":"lt-circulation-1:342fa85c","chapter":"edema","section":"4-why-does-raised-venous-pressure-cause-oedema","type":"mechanism","stem":"A patient develops bilateral ankle oedema after prolonged elevation of systemic venous pressure. What directly drives fluid out of capillaries?","options":{"A":"A reduction in capillary hydrostatic pressure.","B":"A sharp increase in plasma albumin concentration.","C":"An increase in dependent capillary hydrostatic pressure.","D":"A reduction in tissue pressure below atmospheric in every organ."},"answer":"C","why":"Elevated venous pressure transmits into dependent capillaries, increasing outward hydrostatic filtration. Greater outward filtration can exceed the capacity of lymphatic drainage.","not":{"A":"Lower capillary pressure would reduce filtration.","B":"Higher plasma albumin tends to oppose oedema.","D":"The mechanism is raised vascular filtration pressure rather than an obligatory drop in all tissue pressures."}},{"id":"lt-circulation-1:7d310a8f","chapter":"edema","section":"5-why-can-low-plasma-proteins-cause-oedema","type":"application","stem":"Why may advanced liver disease cause generalised oedema even without venous obstruction?","options":{"A":"Excess albumin synthesis draws water into tissues.","B":"Less albumin synthesis reduces plasma oncotic pressure.","C":"A rise in plasma protein concentration stops absorption.","D":"Liver failure directly shuts every lymphatic valve."},"answer":"B","why":"Reduced albumin production lowers intravascular colloid oncotic pressure, allowing more net filtration and oedema.","not":{"A":"Advanced liver disease commonly reduces albumin synthesis.","C":"Plasma protein concentration is decreased, not increased.","D":"Lymphatic valve closure is not the universal mechanism."}},{"id":"lt-circulation-1:7d4d6c7d","chapter":"edema","section":"5-why-can-low-plasma-proteins-cause-oedema","type":"application","stem":"A patient loses substantial albumin into urine during kidney disease. What Starling-force change is expected?","options":{"A":"Increased plasma colloid osmotic pressure.","B":"Reduced capillary permeability everywhere.","C":"Increased red-cell viscosity causing filtration.","D":"Reduced plasma oncotic pressure promotes oedema."},"answer":"D","why":"Proteinuria reduces circulating albumin and its inward oncotic force, favouring movement of fluid into interstitium.","not":{"A":"Albumin loss lowers oncotic pressure.","B":"Capillary permeability elsewhere need not decrease.","C":"Viscosity is not the principal mechanism of protein-loss oedema."}},{"id":"lt-circulation-1:100b1dfa","chapter":"edema","section":"6-how-does-inflammation-increase-oedema","type":"mechanism","stem":"Which mediator released from mast cells can rapidly raise postcapillary venular permeability during inflammation?","options":{"A":"Histamine.","B":"Adenosine.","C":"Nitric oxide.","D":"Angiotensin II."},"answer":"A","why":"Histamine released from mast cells acts on postcapillary venules to increase permeability, allowing plasma proteins and water to move into inflamed tissues.","not":{"B":"Adenosine is primarily a local metabolic vasodilator, rather than the key mast-cell permeability mediator.","C":"Nitric oxide regulates vascular smooth-muscle tone but is not the specified mast-cell mediator.","D":"Angiotensin II principally promotes vasoconstriction and is not a mast-cell permeability signal."}},{"id":"lt-circulation-1:59a6074f","chapter":"edema","section":"8-why-are-pitting-and-non-pitting-oedema-different","type":"clinical-application","stem":"Following regional node removal, a patient develops persistent firm limb swelling. What explains it?","options":{"A":"Raised arterial oxygen causes tightness.","B":"Excess venous flow clears local proteins.","C":"Protein accumulation after failed lymph drainage.","D":"Systolic ejection fraction necessarily becomes reduced."},"answer":"C","why":"Lymphatic obstruction impairs removal of interstitial proteins and fluid, leading over time to persistent, often non-pitting swelling.","not":{"A":"Oxygen delivery is not the main mechanism.","B":"Impaired lymph drainage prevents, rather than accelerates, interstitial protein removal.","D":"Cardiac ejection fraction need not be abnormal."}},{"id":"lt-circulation-1:fb04a533","chapter":"edema","section":"9-which-location-of-oedema-suggests-which-mechanism","type":"comparison","stem":"Which finding would most strongly suggest pulmonary rather than isolated dependent leg oedema?","options":{"A":"Swelling that worsens around the ankles during standing.","B":"Lung crackles and dyspnoea with left-heart failure.","C":"A unilateral swollen arm after mastectomy.","D":"Skin indentation remaining after pressing the ankle."},"answer":"B","why":"Left ventricular failure raises pulmonary venous pressure, causing lung interstitial and alveolar fluid with breathlessness and crackles.","not":{"A":"Dependent leg oedema is more commonly systemic venous or local hydrostatic.","C":"Postmastectomy swelling suggests lymphatic obstruction.","D":"Pitting alone does not localise oedema to the lungs."}},{"id":"lt-circulation-1:7609eef2","chapter":"lymphatics","section":"1-why-do-we-need-lymphatic-vessels-if-we-already-have-veins","type":"conceptual","stem":"What essential material do lymphatics return that would otherwise accumulate in interstitial tissues?","options":{"A":"Only oxygen carried on haemoglobin.","B":"Only glucose absorbed through gut capillaries.","C":"Arterial blood directly from the aorta.","D":"Filtered fluid and escaped plasma proteins."},"answer":"D","why":"Lymphatics return excess interstitial fluid and proteins to the bloodstream, maintaining tissue fluid balance.","not":{"A":"Lymph does not mainly carry oxygen on red-cell haemoglobin.","B":"Glucose generally enters blood capillaries directly.","C":"Lymphatic vessels do not connect to the aorta as arterial conduits."}},{"id":"lt-circulation-1:c846ad27","chapter":"lymphatics","section":"2-how-does-lymph-enter-a-lymphatic-capillary","type":"mechanism","stem":"How can fluid enter a blind-ended lymphatic capillary when interstitial pressure rises?","options":{"A":"Overlapping endothelial flaps admit interstitial fluid.","B":"A central lymphatic heart pumps blood into tissues.","C":"Rigid endothelial junctions prevent all protein entry.","D":"A continuous layer of smooth muscle forces plasma outward."},"answer":"A","why":"Initial lymphatic endothelial flaps allow interstitial fluid and proteins to enter when surrounding pressure exceeds lymphatic pressure.","not":{"B":"There is no single central lymphatic heart.","C":"Initial lymphatics are relatively permeable to interstitial proteins.","D":"Initial lymphatic capillaries lack a thick continuous smooth-muscle coat."}},{"id":"lt-circulation-1:869fec07","chapter":"lymphatics","section":"3-how-can-lymph-move-when-there-is-no-central-lymphatic-heart","type":"mechanism","stem":"What keeps tissue fluid moving through collecting lymph vessels toward the great veins?","options":{"A":"Only the left ventricular ejection pressure.","B":"Constant backflow from the vena cava.","C":"Valves, muscle movement and lymphatic contractions.","D":"Direct diffusion of whole lymph vessels through tissues."},"answer":"C","why":"One-way valves, skeletal-muscle compression, respiratory movement and lymphatic smooth-muscle contraction promote forward flow. The valves prevent reflux between compressions, making the low-pressure pumping effective.","not":{"A":"Lymph flow is not driven directly by systemic arterial pressure.","B":"Backflow is limited by valves rather than required for transport.","D":"Whole vessels do not diffuse through tissues."}},{"id":"lt-circulation-1:aa98b32a","chapter":"lymphatics","section":"4-where-does-lymph-finally-return-to-blood","type":"anatomy","stem":"Where does most body lymph ultimately rejoin circulating blood?","options":{"A":"Directly into the right ventricle.","B":"Thoracic duct into the left venous angle.","C":"Through pulmonary capillaries into the left atrium.","D":"Through coronary sinus into the right atrium."},"answer":"B","why":"The thoracic duct drains most lymph into the left subclavian–internal jugular venous junction. The right lymphatic duct drains a smaller portion of the body into the right venous angle.","not":{"A":"Lymphatic ducts empty into systemic veins, not directly ventricles.","C":"Pulmonary capillaries are not the outlet of the thoracic duct.","D":"The coronary sinus carries venous blood from myocardium."}},{"id":"lt-circulation-1:c6d5c54b","chapter":"lymphatics","section":"5-why-is-the-intestinal-lymphatic-system-important-in-fat-absorption","type":"mechanism","stem":"After a meal containing long-chain fats, which pathway carries these lipids from the gut?","options":{"A":"Direct red-cell delivery to lacteals.","B":"Renal filtration of absorbed fats.","C":"Oxygenated blood flow through the portal vein alone.","D":"Chylomicron transport from intestinal lacteals."},"answer":"D","why":"Absorbed long-chain fats are packaged into chylomicrons and enter lacteals, reaching the blood via lymphatic drainage.","not":{"A":"Red cells normally remain in blood vessels.","B":"Kidneys do not mediate initial intestinal fat absorption.","C":"Most long-chain dietary fat reaches systemic blood through lymph rather than directly through portal blood."}},{"id":"lt-circulation-1:7b43c3ff","chapter":"lymphatics","section":"7-why-does-lymphatic-obstruction-cause-lymphoedema","type":"application","stem":"Why can longstanding filarial lymphoedema become firm and poorly pitting?","options":{"A":"Chronic protein-rich interstitial fluid promotes tissue fibrosis.","B":"Ongoing rapid capillary reabsorption removes tissue proteins.","C":"Longstanding venous dilation prevents connective-tissue changes.","D":"A brief loss of arterial pressure causes permanent limb scarring."},"answer":"A","why":"Persistent failure of lymphatic drainage leaves protein-rich fluid in the interstitium, promoting chronic inflammation and fibrosis. This explains why longstanding lymphoedema becomes firm and often non-pitting.","not":{"B":"Rapid reabsorption would tend to reduce swelling and protein accumulation.","C":"Chronic interstitial protein deposition can drive fibrosis despite any venous tone changes.","D":"The chronic fibrosis is linked to sustained lymphatic obstruction, not a brief arterial-pressure change."}}]};
